export interface PrivateFrame {
    skuId: string;
    title: string;
    label: string;
    layers: { id: string; type: string; order: string; anchor: string; responsive: boolean; }[];
    urls: Record<string, string>;
    thumb: string;
}

// The sizes Discord uses for every frame: a 1200 wide card, 160 px of frame above it, 190 below, 56 each side.
export const FRAME_SIZES = { innerWidth: 1200, overflowTop: 160, overflowBottom: 190, overflowHorizontal: 56 } as const;

